#!/usr/bin/env bash
set -Eeuo pipefail
BASE_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"; report="$BASE_DIR/resultado/ultimo.log"; mkdir -p "$(dirname "$report")"
verify(){ [[ -d "$BASE_DIR/.venv" ]] || python3 -m venv "$BASE_DIR/.venv"; "$BASE_DIR/.venv/bin/pip" -q install -r "$BASE_DIR/backend/requirements-dev.txt"; "$BASE_DIR/.venv/bin/flake8" --config="$BASE_DIR/../.flake8" --extend-exclude=tests "$BASE_DIR/backend"; (cd "$BASE_DIR" && PYTHONPATH=backend .venv/bin/pytest -q backend/tests); command -v yamllint >/dev/null && yamllint -c "$BASE_DIR/.yamllint.yml" "$BASE_DIR/docker-compose.yml" "$BASE_DIR/../.github/workflows"; command -v docker >/dev/null && (cd "$BASE_DIR" && docker compose config -q); }
case ${1:-} in iniciar) if [[ ${OPERACIONES_GLOBAL:-0} == 1 ]]; then echo 'TP07 amplía TP06 y no agrega servicios permanentes en modo global.' | tee "$report"; else verify | tee "$report"; fi;; detener) echo 'Guía 07: no existen servicios permanentes.';; reiniciar) "$0" iniciar;; estado) test -f "$BASE_DIR/../.github/workflows/cicd.yml" && echo 'TP07 preparado';; verificar) verify | tee "$report";; logs) test -f "$report" && cat "$report" || echo 'Sin reporte';; *) echo "Uso: $0 {iniciar|detener|reiniciar|estado|verificar|logs}" >&2; exit 64;; esac
